#!/usr/bin/env bash
# R11 boss lane art: four boss cats, the wooden milestone chest, the gold boss chest, the streak flame and the castle
# map node. ONE at a time via studio/bin/art.sh. Processed by proc_boss.py. usage: boss.sh [name...]  (FORCE=1 to redo)
cd "$(dirname "$0")"
S="Art style (must match across the whole set): soft painterly 3D cartoon like a polished 2026 mobile game, smooth chunky rounded felt-toy shapes, clean soft shading and gentle gradients, NOT photorealistic, NOT flat vector, no outlines. Palette: sage green walls #689A8D, honey oak wood #BF7948 with darker oak #8E5530, ivory #FFF0D3, rust red #BD582F, warm cream #fff6e5. One warm sunlight from the upper right, soft shadows falling down-left. Absolutely no text, no letters, no numbers, no logo, no watermark."
K="Place every item on a flat solid pure magenta #ff00ff background with nothing else on it so it can be keyed out; no shadow on the background, items must not touch each other or the image edge."
B="Single character, full body, sitting upright facing the viewer in a slight three-quarter view, a HUGE chonky round cat boss twice as wide as a normal cat, big round belly, tiny paws, funny and lovable, never scary, expressive big eyes and eyebrows."
g(){ n=$1; shift; if [ -s "$n.png" ] && [ -z "$FORCE" ]; then echo "skip $n"; return; fi; echo "gen $n $(date +%T)"; timeout 600 /c/Users/Admin/Documents/Msjelly/studio/bin/art.sh "$(pwd -W)/$n.png" "$*" >/dev/null 2>&1; ls -la "$n.png" 2>&1 | awk '{print $5}'; }
W=("$@")
run(){ if [ ${#W[@]} -eq 0 ]; then return 0; fi; for w in "${W[@]}"; do [ "$w" = "$1" ] && return 0; done; return 1; }
run boss_duke && g boss_duke "$B A fluffy cream and silver-grey Persian cat as a pompous duke: a round gold monocle on one eye, a tiny burgundy velvet top hat, a frilly white cravat, paws folded over the belly, an indignant grumpy frown with puffed cheeks. $K $S"
run boss_pirate && g boss_pirate "$B An orange tabby cat as a pirate captain: a black tricorn hat with gold trim, a black eye patch, a gold hoop earring, a red and cream striped sash round the belly, holding up a big fish bone like a sword, a scowling cheeky smirk. $K $S"
run boss_chef && g boss_chef "$B A white cat with a pink nose as a grumpy head chef: a tall puffy white chef toque, a red neckerchief, a white double-breasted chef jacket stretched tight over the belly, holding a honey-oak rolling pin, bushy whisker moustache, a stern scowl. $K $S"
run boss_wizard && g boss_wizard "$B A blue-grey Russian Blue cat as a wizard: a tall floppy violet pointed hat with yellow stars, a long fluffy white beard, a violet robe, holding a short honey-oak wand with a glowing yellow star on the tip, a scheming mischievous frown. $K $S"
run chest_wood && g chest_wood "Two items side by side with a wide magenta gap, same scale and same three-quarter view: (1) a small sturdy honey-oak wooden treasure chest, CLOSED, rounded lid, dark iron bands and corner caps, a brass latch with a paw-print shaped lock, chunky toy-like; (2) the SAME chest with the lid flung OPEN backwards, the inside empty and glowing with warm golden light. $K $S"
run chest_gold && g chest_gold "Two items side by side with a wide magenta gap, same scale and same three-quarter view: (1) a big royal treasure chest, CLOSED, shiny gold metal frame with deep red velvet panels, a gold crown-shaped lock on the front, round rubies on the corners, a domed lid, chunky toy-like and a little bigger than a normal chest; (2) the SAME chest with the lid flung OPEN backwards, the inside empty with bright golden light beaming up out of it. $K $S"
run boss_icons && g boss_icons "Two items side by side with a wide magenta gap: (1) a chunky cute flame icon, a teardrop-shaped orange and golden-yellow fire with a lighter yellow core and two small pointed cat ears on top, glossy; (2) a small storybook castle map marker: a round chunky stone tower castle with crenellations, a big arched honey-oak door, a red pointed roof and a little red and gold pennant flag with no emblem, standing on a small round grassy base, three-quarter view. $K $S"
